import{_ as r,J as t,b as s,e as i,a8 as n,f as o,L as c}from"./chunks/framework.C-MVLAPI.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Rasterizers","entity":"TRasterizer","kind":"Class","abstract":true,"aliases":["TRasterizerClass"],"declaration":"type\\n  TRasterizer = class abstract(TThreadPersistent)\\n    ...\\n  TRasterizerClass = class of TRasterizer;\\n","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TRasterizer"],"summary":"Abstract base class for bitmap-specific rasterizers that transfer spatial samples into target bitmap buffers.","date":1788523740000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Rasterizers/TRasterizer/index.md","filePath":"api/GR32_Rasterizers/Classes/TRasterizer/index.md","lastUpdated":1788523740000,"timestamp":1788523740000,"datetime":"2026-09-04T12:09:00.000Z","contributors":[]}'),l={name:"api/GR32_Rasterizers/TRasterizer/index.md"};function d(p,e,m,u,T,R){const a=t("ApiMembers");return s(),i("div",null,[e[0]||(e[0]=n('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TRasterizer</code> serves as the abstract base class for all rasterization engines in Graphics32. Rasterizers iterate across 2D pixel coordinates within a destination bitmap (<a href="/api/GR32/TCustomBitmap32/">TCustomBitmap32</a>), querying color values from an attached <a href="/api/GR32/TCustomSampler/">TCustomSampler</a> and writing the resulting pixels using configurable combination and blend modes (<a href="/api/GR32_Rasterizers/TCombineInfo">TCombineInfo</a>).</p><p>Key capabilities provided by <code>TRasterizer</code> include:</p><ul><li>Managing an attached <a href="/api/GR32/TCustomSampler/">TCustomSampler</a> reference via the <a href="/api/GR32_Rasterizers/TRasterizer/Sampler">Sampler</a> property.</li><li>Handling drawing modes (<code>dmOpaque</code>, <code>dmBlend</code>, <code>dmTransparent</code>, <code>dmCustom</code>) and master alpha transparency.</li><li>Managing sampling life cycle calls (<code>FSampler.PrepareSampling</code> and <code>FSampler.FinalizeSampling</code>).</li><li>Providing flexible overloaded <a href="/api/GR32_Rasterizers/TRasterizer/Rasterize">Rasterize</a> entry points accepting custom target rectangles, combine info records, or source bitmap settings.</li></ul><p>Derived classes override the protected <code>DoRasterize</code> method to implement specialized coordinate traversal and sampling order strategies (such as regular scanlines, swizzling fractal curves, progressive subsampling, or multi-threading).</p>',5)),o("p",null,[c(a,{type:"members"})])])}const b=r(l,[["render",d]]);export{h as __pageData,b as default};
